function UICultivateEquipMain:InitData(parameters)
    local playerCardId = parameters.playerCardId
    self.part = parameters.part or 0

    ---@type CardDojo
    local cardDojo = self:InitCardDojo(playerCardId)

    local cardVo = cardConfMgr:GetCardByRefId(cardDojo.cardId)
    self.career = cardVo.career

    self:InitEquipIdList(cardDojo)
end

function UICultivateEquipMain:InitCardDojo(playerCardId)
    ---@type CardDojo
    local cardDojo = cardComp:GetCardById(playerCardId)
    self.cardDojo = cardDojo
    return cardDojo
end


---InitCurEquipIdList
---初始化当前装备id列表
---@param cardDojo CardDojo
function UICultivateEquipMain:InitEquipIdList(cardDojo)
    local equipIdList = {0, 0, 0, 0}
    local GetEquipIdKeyByPart = EquipUtils.GetEquipIdKeyByPart
    for i = 1, Constants.CardEquipmentNo do
        local key = GetEquipIdKeyByPart(i)
        --- equipment1 equipment2
        equipIdList[i] = checkNumber(cardDojo[key])
    end

    self.originalEquipIdList = clone(equipIdList)
    self.equipIdList = equipIdList
    self.originalEquipmentCoreId = checkNumber(cardDojo.equipmentCore)
end

function UICultivateEquipMain:InitUI()
    self:InitEquipCount()
    self:InitEquipBackpack()
    self:InitListener()
end

function UICultivateEquipMain:InitEquipCount()
    
    local EquipCountText = self.TextEquipCount
    local coreCount      = #equipComp:GetAllEquipCores()
    local equipCount     = #equipComp:GetAllEquips()
    local ownCount       = coreCount + equipCount
    local limitCount     = 6000
    local text           = ownCount > limitCount and string.format("<color=#ff0000>%s</color>/%s", ownCount, limitCount) or string.format("%s/%s", ownCount, limitCount)
    EquipCountText.text = text

    local TextTip        = self.TextTip
    KTool.SetActive(TextTip.gameObject, ownCount > limitCount)

end


