function UICultivateEquipMain:LoadComparedView(curDojo, compareDojo, equipType, part, closeCb)
    if self.ComparedView then
        self:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
        return
    end
    if self.ComparedViewCo then
        return
    end
    self.ComparedViewCo = cs_coroutine.start(function()
        self.ComparedView = GameUtils.LoadBundleAsyncById(EquipComparedViewPrefabId, self.Container.gameObject, false, true)
        self:RefreshComparedView(curDojo, compareDojo, equipType, part, closeCb)
        self.ComparedViewCo = nil
    end)
end

function UICultivateEquipMain:StopComparedViewCo()
