function UICultivateEquipMain:ExecuteEquipmentEquip()
    ---@type CardDojo
    local cardDojo            = self.cardDojo
    local playerCardId        = cardDojo.id
    local equipIdList         = self.equipIdList
    local originalEquipIdList = self.originalEquipIdList
    local isChange            = false
    local equipmentIdList     = {}

    for i = 1, Constants.CardEquipmentNo do
        local originalEquipId = checkNumber(originalEquipIdList[i])
        local equipId = checkNumber(equipIdList[i])
        if originalEquipId ~= equipId then
            isChange = true
        end
        equipmentIdList[tostring(i)] = equipId
    end

    local equipmentCore = checkNumber(cardDojo.equipmentCore)
    if not isChange then
        isChange = self.originalEquipmentCoreId ~= equipmentCore
    end

    if isChange then
        GameUtils.Request(Interfaces.EquipmentEquip, {playerEquipmentCoreId = equipmentCore, playerCardId = playerCardId, equipment = table.serialize(equipmentIdList) }, function(request, response)
            if checkInt(response.errCode) ~= 0 then return end
        end)
    end
end


function UICultivateEquipMain:SaveUIState()
    ---@type UICultivateEquipBackpackNodeMB
    local mbEnv = self:GetEnvByType(self.EquipBackpackNode, EnvType.BackPack)
    if mbEnv == nil then return end
    local backpackCacheData = mbEnv:SaveUIState()
    local parameters = self.controller.Argument.parameters or {}
    parameters.part = self.part
    if next(backpackCacheData) then
        parameters.uiStateParams = backpackCacheData
    end
    self.controller.Argument.parameters = parameters
end

