function UICultivateEquipMain:OnCellClickAction(backpackDataId, part, equipType)
    if backpackDataId <= 0 then return end
    local curDojo, compareDojo
    local equipPart
    if equipType == EquipType.Core then
        curDojo = equipComp:GetEquipCoreById(self.cardDojo.equipmentCore)
        compareDojo = equipComp:GetEquipCoreById(backpackDataId)
        equipPart = -1
    elseif equipType == EquipType.Equip then
        local equipIdList = self.equipIdList
        equipPart = part or self.part
        curDojo = equipComp:GetEquipById(equipIdList[equipPart])
        compareDojo = equipComp:GetEquipById(backpackDataId)

    end
    self:LoadComparedView(curDojo, compareDojo, equipType, equipPart, function()
        ---@type UICultivateEquipBackpackNodeMB
        local mbEnv = self:GetEnvByType(self.EquipBackpackNode, EnvType.BackPack)
        if mbEnv == nil then return end
        mbEnv:HideSelectIndex()
    end)
end

function UICultivateEquipMain:OnUpdatePartAction(part)
    self:SwitchPart(part)
end

function UICultivateEquipMain:OnClickEquipNodeGroupAction(part)
    self:SwitchPart(part, true)

    local curDojo, equipType
    if part == -1 then
        curDojo = equipComp:GetEquipCoreById(self.cardDojo.equipmentCore)
        equipType = EquipType.Core
    else
        curDojo = equipComp:GetEquipById(self.equipIdList[part])
        equipType = EquipType.Equip
    end
    if curDojo and self.part ~= 0 then
        self:LoadComparedView(curDojo, nil, equipType, part)
    end
end

function UICultivateEquipMain:OnClickUninstallButtonAction()
    local coreId = checkNumber(self.cardDojo.equipmentCore)
    if not EquipUtils.CheckIsInstallEquip(self.equipIdList) and coreId <= 0 then
        GameUtils.Toast(localize("当前卡牌未安装过装备"))
        return
    end

    GameUtils.SecondConfirm(localize("是否全部卸载？"), function()
        local playerCardId = self.cardDojo.id
        --------------------------
        --- update cache data

        local cardDojo = cardComp:RemoveAllEquipById(playerCardId)
        self.cardDojo = cardDojo
        --------------------------

        --------------------------
        --- update backpack
        ---@type UICultivateEquipBaseBackpackNodeMB
        local mbEnv = self:GetEnvByType(self.EquipBackpackNode, EnvType.BackPack)
        if mbEnv then
            mbEnv:ClearSelectData()
            mbEnv:SetEquipIdList({0,0,0,0})
            mbEnv:SetPlayerEquipCoreId(0)
            mbEnv:AddSuitDataPartListByEquipIdList(self.equipIdList)
            mbEnv:AddSuitDataPartListByCoreId(coreId)
            mbEnv:ReloadScrollView()
        end
        --------------------------

        self.equipIdList = {0,0,0,0}

        --------------------------
        --- update UI
        self:RefreshEquipInfoNode()
        --------------------------
    end)
end

