function UICultivateEquipMain:OnEventOperateEquipOrCore(params, equipType, direction)
    local isLeft = direction == 1
    local status = params.status
    local dojo   = params.dojo
    local part   = params.part
    local playerCardId = self.cardDojo.id

    if isLeft then
        self:EnterCultivateEquipDialog(dojo.id)
        return
    -- elseif status == Status.CultivateAndInstall or status == Status.CultivateAndReplace then
    --     if checkNumber(dojo.playerCardId) > 0 then
    --         GameUtils.Toast(localize("该涂鸦已被其他武装装备"))
    --         return
    --     end
    end

    local t = {
        [Status.CultivateAndInstall] = Status.Install,
        [Status.CultivateAndReplace] = Status.Replace,
        [Status.CultivateAndUninstall] = Status.Uninstall,
    }
    local realStatus = t[status] or status
    self:UpdateCardOnEquipOrCore(playerCardId, dojo, equipType, part, realStatus)

end

function UICultivateEquipMain:UpdateCardOnEquipOrCore(playerCardId, dojo, equipType, part, status)
    local isUninstall = status == Status.Uninstall
    local isEquip = equipType == EquipType.Equip
    local id = checkNumber(dojo.id)

    local backpackNewId, backpackOldId = self:GetBackpackNewIdAndOldIdByStatus(status, id, part, isEquip)
    local equipmentCoreDojo
    if isEquip then
        local func = isUninstall and equipComp.RemoveCardOnEquip or equipComp.AddCardOnEquip
        func(equipComp, playerCardId, id, part)

        local equipId = isUninstall and 0 or id
        self.equipIdList[part] = equipId

        equipmentCoreDojo = equipComp:GetEquipCoreById(self.cardDojo.equipmentCore)
    else
        local func = isUninstall and equipComp.RemoveCardOnEquipCore or equipComp.AddCardOnEquipCore
        func(equipComp, playerCardId, id)
    end

    --- 1. 重新初始化 CardDojo
    ---@type CardDojo
    self:InitCardDojo(playerCardId)

    ---2. 更新装备背包
    self:RefreshBackpackDataAndRefreshList(backpackNewId, backpackOldId, part)

    ---3. 更新装备或核心节点
    self:RefreshEquipNodeGroupByPart(part, dojo, equipmentCoreDojo, isUninstall)

    ---4. 更新套装描述和属性节点
    self:RefreshSuitDescAndAttrNode(true)
end

function UICultivateEquipMain:GetBackpackNewIdAndOldIdByStatus(status, id, part, isEquip)
    local backpackNewId, backpackOldId = 0, 0
    --- 卸载 backpackNewId = id, backpackOldId = 0
    --- 安装 backpackNewId = 0, backpackOldId = id
    --- 替换 backpackNewId = 卡牌身上的装备或核心id, backpackOldId = id

    if status == Status.Install or status == Status.CultivateAndInstall then
        backpackOldId = id
    elseif status == Status.Uninstall then
        backpackNewId = id
    elseif status == Status.Replace or status == Status.CultivateAndReplace then
        backpackNewId = isEquip and self.equipIdList[part] or checkNumber(self.cardDojo.equipmentCore)
        backpackOldId = id
    end
    return backpackNewId, backpackOldId

end

function UICultivateEquipMain:OnClickBtnReclaimAction()
    --- 过滤方法
    local function filter(dojo)
        return checkNumber(dojo.playerCardId) == 0 and checkNumber(dojo.locked) == 0
    end

    local t = {}
    ---@type EquipDojo[]
    local equipDojos = equipComp:GetAllEquips()
    local temp = {}
    for i, v in ipairs(equipDojos) do
        if filter(v) then
            table.insert(t, EquipUtils.GenerateEquipDataByDojo(v, temp))
        end
    end

    temp = {}
    ---@type EquipmentCoreDojo[]
    local equipCores = equipComp:GetAllEquipCores()
    for i, v in ipairs(equipCores) do
        if filter(v) then
            table.insert(t, EquipUtils.GenerateCoreDataByDojo(v, temp))
        end
    end

    if next(t) == nil then
        GameUtils.Toast(localize("无可回收的情绪涂鸦"))
        return
    end

    UIModule.OpenDialog({ id = Constants.UITypeIds.UICultivateEquipReclaimDialog,
                          parameters = {
                              dataList = t
                          }
    }, {
        {id = Constants.UITypeIds.UICultivateEquipMainDialog}
    })
end

